```{.r .cell-code  code-line-numbers="1|2|3-4|6-9"}
histobar <- function(df, var){
  if(is.numeric(class({{var}}))){
    ggplot(df, aes(x = {{var}})) + 
      geom_histogram(col = "white")
  }
  else {
    ggplot(df, aes(y = {{var}})) + 
      geom_bar()
  }
}
